const dishes=[
{name:'Saffron Chicken Mandi',price:18,category:'signature',image:'photo-1563379091339-03246963d96c',badge:'THE HOUSE FAVOURITE',text:'Slow-roasted chicken, saffron basmati, toasted nuts & our signature smoky daqoos.',tag:'SLOW COOKED · SERVES 1',allergens:'Contains nuts. Served with tomato daqoos and a fresh side salad.'},
{name:'The Sahra Lamb Feast',price:28,category:'signature',image:'photo-1544025162-d76694265947',badge:'MADE TO SHARE',text:'Tender spiced lamb, fragrant rice and a generous spoonful of warm hospitality.',tag:'FROM THE HEARTH',allergens:'Contains dairy and nuts. A generous plate for one or a shared centrepiece.'},
{name:'Garden on a Plate',price:14,category:'signature',image:'photo-1512621776951-a57141f2eefd',badge:'V · PLANT FORWARD',text:'Roasted seasonal vegetables, herby grains, pomegranate & a bright tahini drizzle.',tag:'FRESH · COLOURFUL · VEGETARIAN',allergens:'Contains sesame. Vegetarian.'},
{name:'Silky Hummus',price:7,category:'mezze',image:'photo-1577805947697-89e18249d767',badge:'V · FOR THE MIDDLE',text:'Chickpeas whipped with tahini, extra virgin olive oil and a dusting of sumac.',tag:'SCOOP. DIP. REPEAT.',allergens:'Contains sesame and wheat in accompanying flatbread. Vegetarian.'},
{name:'Pistachio Baklava',price:8,category:'sweet',image:'photo-1519676867240-f03562e64548',badge:'A SWEET LITTLE FINISH',text:'Golden pastry, crushed pistachios and fragrant orange-blossom syrup.',tag:'BEST WITH A CUP OF TEA',allergens:'Contains wheat, dairy and pistachios. Vegetarian. Image is an illustrative dessert.'},
{name:'Mint Tea Ritual',price:4,category:'drinks',image:'photo-1544787219-7f47ccb76574',badge:'POURED WITH LOVE',text:'Fresh mint, delicate tea and a moment to slow down. Sweeten it your way.',tag:'FRESHLY BREWED',allergens:'No listed common allergens. Served hot with sugar on the side.'}
];
const grid=document.querySelector('#dishes');const modal=document.querySelector('dialog');
function render(filter='all'){grid.replaceChildren();dishes.forEach((dish,i)=>{if(filter!=='all'&&dish.category!==filter)return;const card=document.createElement('button');card.className='dish';card.setAttribute('aria-label',`View ${dish.name} details`);card.innerHTML=`<div class="dish-visual"><img src="https://images.unsplash.com/${dish.image}?auto=format&fit=crop&w=800&q=80" alt="${dish.name}" loading="lazy"><span class="badge">${dish.badge}</span></div><div class="dish-title"><h3>${dish.name}</h3><span class="price">$${dish.price}</span></div><p>${dish.text}</p><div class="dish-bottom"><span>${dish.tag}</span><b>↗</b></div>`;card.addEventListener('click',()=>{document.querySelector('#dialog-content').innerHTML=`<img src="https://images.unsplash.com/${dish.image}?auto=format&fit=crop&w=800&q=80" alt="${dish.name}"><h2>${dish.name} <em>$${dish.price}</em></h2><p>${dish.text}</p><p class="detail">${dish.allergens}</p><p class="detail">Illustrative concept menu. This website does not accept orders.</p>`;modal.showModal()});grid.append(card)})}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});render(button.dataset.filter)}));document.querySelector('.close').addEventListener('click',()=>modal.close());modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close()}});document.querySelector('#year').textContent=new Date().getFullYear();document.querySelectorAll('[data-filter]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===0)));render();
